css:
.liwanag-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2118;
    background: linear-gradient(165deg, #f7f1e6 0%, #f1ebdd 55%, #ece4d3 100%);
    border-radius: 18px;
}

.liwanag-container * {
    box-sizing: border-box;
}

.liwanag-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #4a2f17 0%, #6f4521 50%, #2f6b3a 100%);
    color: #fbf6ec;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(74, 47, 23, 0.32);
}

.liwanag-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.liwanag-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f2cf83;
    background: rgba(242, 207, 131, 0.14);
    border: 1px solid rgba(242, 207, 131, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.liwanag-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ecdfc8;
}

.liwanag-firms {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.liwanag-firm {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(74, 47, 23, 0.10);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.liwanag-firm-core { border-left: 5px solid #2f6b3a; }
.liwanag-firm-foundation { border-left: 5px solid #b5852f; }

.liwanag-firm-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #4a2f17;
}

.liwanag-firm-core .liwanag-firm-name { color: #2f6b3a; }
.liwanag-firm-foundation .liwanag-firm-name { color: #a9781f; }

.liwanag-firm-meta {
    font-size: 0.82rem;
    color: #6b5c47;
    line-height: 1.4;
}

.liwanag-firm-vs {
    align-self: center;
    font-size: 1.1rem;
    font-weight: 800;
    color: #8a6a3c;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.liwanag-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a4a36;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.liwanag-period-counter #currentDay,
.liwanag-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f6b3a;
}

.liwanag-round-name {
    background: rgba(47, 107, 58, 0.14);
    color: #245930;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.liwanag-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #976c1c;
    background: rgba(181, 133, 47, 0.16);
    border: 1px solid rgba(181, 133, 47, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.liwanag-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.liwanag-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(74, 47, 23, 0.09);
    border-top: 4px solid #6f4521;
}

.liwanag-card-roi { border-top-color: #1f6f8b; }
.liwanag-card-impact { border-top-color: #2f6b3a; }
.liwanag-card-supply { border-top-color: #b5852f; }
.liwanag-card-moat { border-top-color: #7d4ea8; }

.liwanag-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6a54;
}

.liwanag-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #4a2f17;
    font-variant-numeric: tabular-nums;
}

.liwanag-card-roi .liwanag-value { color: #1f6f8b; }
.liwanag-card-impact .liwanag-value { color: #2f6b3a; }
.liwanag-card-supply .liwanag-value { color: #a9781f; }
.liwanag-card-moat .liwanag-value { color: #7d4ea8; }

.liwanag-sublabel {
    font-size: 0.76rem;
    color: #8a7a62;
    line-height: 1.35;
}

/* ROI relative to the 18% hurdle: clears = green, misses = red. */
.liwanag-card-roi.liwanag-roi-clears { border-top-color: #2f8f4a; }
.liwanag-card-roi.liwanag-roi-clears .liwanag-value { color: #2f8f4a; }
.liwanag-card-roi.liwanag-roi-misses { border-top-color: #c0392b; }
.liwanag-card-roi.liwanag-roi-misses .liwanag-value { color: #c0392b; }

.liwanag-card-supply.liwanag-supply-low { border-top-color: #c0392b; }
.liwanag-card-supply.liwanag-supply-low .liwanag-value { color: #c0392b; }
.liwanag-card-moat.liwanag-moat-weak .liwanag-value { color: #c0392b; }

.liwanag-verdict-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e3d8c2;
    color: #5a4a36;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.liwanag-verdict-bar #verdictDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #c0392b;
    font-weight: 800;
    text-align: right;
}

.liwanag-verdict-bar.liwanag-verdict-mid #verdictDisplay { color: #b5852f; }
.liwanag-verdict-bar.liwanag-verdict-good #verdictDisplay { color: #2f8f4a; }

.liwanag-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f6b3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 47, 23, 0.08);
}

.liwanag-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.liwanag-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #4a2f17;
    margin-bottom: 6px;
}

.liwanag-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4c4030;
}

.liwanag-briefing-text strong { color: #2f6b3a; }
.liwanag-briefing-text em { color: #a9781f; font-style: italic; }

.liwanag-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 47, 23, 0.08);
}

.liwanag-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #4a2f17;
    border-bottom: 2px solid #ece2cf;
    padding-bottom: 8px;
}

.liwanag-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3c3122;
    margin: 14px 0 6px;
}

.liwanag-container select,
.liwanag-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d4c6ac;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2a2118;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.liwanag-container select:focus,
.liwanag-container input[type="number"]:focus {
    outline: none;
    border-color: #2f6b3a;
    box-shadow: 0 0 0 3px rgba(47, 107, 58, 0.16);
}

.liwanag-container select option {
    background-color: #ffffff;
    color: #2a2118;
}

.liwanag-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f6b3a;
}

.liwanag-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a4a36;
    margin-top: 4px;
}

.liwanag-range-readout span:nth-child(2) {
    color: #2f6b3a;
    font-weight: 800;
}

.liwanag-hint {
    font-size: 0.8rem;
    color: #8a7a62;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.liwanag-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.liwanag-container .btn-primary {
    background: linear-gradient(135deg, #2f6b3a 0%, #3f8a3f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 107, 58, 0.32);
}

.liwanag-container .btn-primary:hover {
    filter: brightness(1.07);
}

.liwanag-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d4c6ac;
    color: #6b5c47;
    background: transparent;
}

.liwanag-coach {
    background: linear-gradient(160deg, #4a2f17 0%, #5e3c1d 100%);
    color: #f3e8d6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(74, 47, 23, 0.26);
}

.liwanag-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f2cf83;
    margin-bottom: 8px;
}

.liwanag-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.liwanag-coach-body strong { color: #8fd99a; }
.liwanag-coach-body em { color: #f2cf83; font-style: italic; }

.liwanag-history,
.liwanag-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 47, 23, 0.08);
}

.liwanag-history h3,
.liwanag-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #4a2f17;
}

.liwanag-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4c4030;
}

.liwanag-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #6f4521;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d4bd;
}

.liwanag-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eadd;
    color: #4c4030;
}

.liwanag-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf6ed;
}

.liwanag-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .liwanag-container {
        padding: 14px;
    }
    .liwanag-header h1 {
        font-size: 1.7rem;
    }
    .liwanag-firms {
        flex-direction: column;
    }
    .liwanag-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .liwanag-value {
        font-size: 2rem;
    }
    .liwanag-clock {
        margin-left: 0;
    }
    .liwanag-period-counter {
        font-size: 0.88rem;
    }
    .liwanag-verdict-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .liwanag-verdict-bar #verdictDisplay {
        text-align: left;
    }
    .liwanag-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================
   Innovate for Impact — completion debrief (v1.1.0, append-only)
   Namespaced .ii-cm-* ; rendered into #usf-completion-content.
   ============================================================ */
.ii-cm { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #1f2a37; }
.ii-cm-verdict { display: flex; align-items: center; gap: 18px; padding: 16px 18px; border-radius: 12px;
    background: linear-gradient(135deg, #f3f0fb 0%, #eef6f2 100%); border: 1px solid #e3dcee; margin-bottom: 18px; }
.ii-cm-top .ii-cm-verdict { background: linear-gradient(135deg, #efe8fb 0%, #e5f4ec 100%); border-color: #7c5cbf; }
.ii-cm-score { flex: 0 0 auto; min-width: 92px; text-align: center; line-height: 1; }
.ii-cm-score-num { font-size: 2.9rem; font-weight: 800; color: #7c5cbf; }
.ii-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #7688a0; }
.ii-cm-top .ii-cm-score-num { color: #1f8f5f; }
.ii-cm-verdict-txt { flex: 1 1 auto; }
.ii-cm-badge { font-size: 1.35rem; font-weight: 700; color: #1f2a37; margin-bottom: 3px; }
.ii-cm-sub { font-size: 0.9rem; color: #7688a0; }
.ii-cm-h { font-size: 0.82rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: #46596b; margin: 16px 0 8px; }
.ii-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ii-cm-chip { display: inline-flex; align-items: center; gap: 5px; padding: 5px 11px; border-radius: 16px; font-size: 0.86rem; font-weight: 600; border: 1px solid transparent; }
.ii-cm-chip-ok { background: rgba(31,143,95,0.12); color: #1f8f5f; border-color: rgba(31,143,95,0.32); }
.ii-cm-chip-no { background: rgba(214,69,69,0.10); color: #b23b3b; border-color: rgba(214,69,69,0.30); }
.ii-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 10px; }
.ii-cm-kpi { background: #f7f6fc; border: 1px solid #eae6f4; border-radius: 10px; padding: 11px 12px; text-align: center; }
.ii-cm-kpi-val { font-size: 1.25rem; font-weight: 800; color: #1f2a37; }
.ii-cm-kpi-lbl { font-size: 0.76rem; font-weight: 600; color: #46596b; margin-top: 3px; line-height: 1.2; }
.ii-cm-kpi-sub { font-size: 0.7rem; color: #93a3b3; margin-top: 2px; }
.ii-cm-insights { margin: 0; padding-left: 18px; }
.ii-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #33414f; margin-bottom: 7px; }
.usf-dark .ii-cm { color: #e6edf3; }
.usf-dark .ii-cm-verdict { background: linear-gradient(135deg, #221b32 0%, #1a2a24 100%); border-color: #382c4c; }
.usf-dark .ii-cm-badge { color: #e6edf3; }
.usf-dark .ii-cm-kpi { background: #1e1a2c; border-color: #322a44; }
.usf-dark .ii-cm-kpi-val { color: #e6edf3; }
.usf-dark .ii-cm-insights li { color: #c4d0dc; }

