(function() {
    'use strict';

    class InnovateForImpactAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Innovate for Impact`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Liwanag Consumer Group). ----
            this.HURDLE = 18;            // 18% financial hurdle rate
            this.IMPACT_THRESHOLD = 60;  // inclusive-growth index threshold (0–100)
            this.SUPPLY_TARGET = 95;     // % of required coffee volume to be "secured"
            this.MOAT_TARGET = 60;       // defensibility / barrier-to-imitation threshold
            this.ENVELOPE = 1.2;         // ₱1.2bn three-year envelope

            // ---- Starting state (post-shock baseline). ----
            this.START_ROI = 9;          // blended return before the strategy (below hurdle)
            this.START_IMPACT = 28;      // inclusive-growth index at day 1
            this.START_SUPPLY = 78;      // 22% of coffee unsecured -> 78% secured
            this.START_MOAT = 22;        // disconnected CSR -> no defensible advantage
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    roi: this.START_ROI,         // blended 3-yr return (%)
                    impact: this.START_IMPACT,   // inclusive-growth index (0–100)
                    supply: this.START_SUPPLY,   // coffee supply secured (%)
                    moat: this.START_MOAT,       // competitive advantage / defensibility (0–100)

                    // ---- Sticky, run-defining penalty flags (set when an error is
                    // committed; they GATE the top verdict and CAP the KPIs so a later
                    // good round cannot wash them out). ----
                    philanthropyRun: false,  // scaled the foundation = the headline anti-pattern
                    extractionRun: false,    // squeezed farmers / spot-market = extractive sourcing
                    splitBudgetRun: false,    // split impact and ROI into two budgets
                    noOwnershipRun: false,    // no P&L ownership in the core business
                    copyableRun: false,       // differentiation with no barrier to imitation
                    delisted: false,          // ESG customer de-listed (lost 15% of revenue)

                    roiHistory: [this.START_ROI],
                    impactHistory: [this.START_IMPACT],
                    supplyHistory: [this.START_SUPPLY],
                    moatHistory: [this.START_MOAT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the COMMON ERRORS — a blind
                // click-through must land in "philanthropy in disguise", not auto-win.
                state.decisions = {
                    diagnosis: `underfunded`,
                    cocreate: `relief`,
                    institutionalize: `biggerfoundation`,
                    urgency: 35,
                    model: `scalecsr`,
                    embed: `bolton`,
                    moatSource: `claim`,
                    integration: 30,
                    alloc: `splitbudget`,
                    governance: `sustainabilityoffice`,
                    drivers: `none`,
                    metric: `goodwill`,
                    hurdle: 40,
                    defense: `goodwill`,
                    shockSelect: `competitor`,
                    response: `philanthropy`,
                    proof: `donated`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const di = document.getElementById(`diagnosisInput`);
                const co = document.getElementById(`cocreateInput`);
                const ins = document.getElementById(`institutionalizeInput`);
                const ur = document.getElementById(`urgencyInput`);
                if (di) decisions.diagnosis = di.value;
                if (co) decisions.cocreate = co.value;
                if (ins) decisions.institutionalize = ins.value;
                if (ur) decisions.urgency = parseInt(ur.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const mo = document.getElementById(`modelInput`);
                const em = document.getElementById(`embedInput`);
                const ms = document.getElementById(`moatSourceInput`);
                const ig = document.getElementById(`integrationInput`);
                if (mo) decisions.model = mo.value;
                if (em) decisions.embed = em.value;
                if (ms) decisions.moatSource = ms.value;
                if (ig) decisions.integration = parseInt(ig.value, 10);
                if (!Number.isFinite(decisions.integration) || decisions.integration < 0 || decisions.integration > 100) {
                    warn(`warn_integration_range`); return false;
                }
            } else if (round === 3) {
                const al = document.getElementById(`allocInput`);
                const go = document.getElementById(`governanceInput`);
                const dr = document.getElementById(`driversInput`);
                const me = document.getElementById(`metricInput`);
                const hu = document.getElementById(`hurdleInput`);
                if (al) decisions.alloc = al.value;
                if (go) decisions.governance = go.value;
                if (dr) decisions.drivers = dr.value;
                if (me) decisions.metric = me.value;
                if (hu) decisions.hurdle = parseInt(hu.value, 10);
                if (!Number.isFinite(decisions.hurdle) || decisions.hurdle < 0 || decisions.hurdle > 100) {
                    warn(`warn_hurdle_range`); return false;
                }
            } else if (round === 4) {
                const de = document.getElementById(`defenseInput`);
                const ss = document.getElementById(`shockSelectInput`);
                const re = document.getElementById(`responseInput`);
                const pr = document.getElementById(`proofInput`);
                const cv = document.getElementById(`convictionInput`);
                if (de) decisions.defense = de.value;
                if (ss) decisions.shockSelect = ss.value;
                if (re) decisions.response = re.value;
                if (pr) decisions.proof = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let roiDelta = 0, impactDelta = 0, supplyDelta = 0, moatDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose: philanthropy or strategy? ----
                switch (d.diagnosis) {
                    case `disconnected`: moatDelta += 6; impactDelta += 2; coachKey = `coach_r1_disconnected`; break;
                    case `underfunded`: moatDelta -= 2; coachKey = `coach_r1_underfunded`; break;
                    case `pr`: moatDelta -= 3; coachKey = `coach_r1_pr`; break;
                }

                switch (d.cocreate) {
                    case `supplybase`: moatDelta += 6; supplyDelta += 3; impactDelta += 3; coachKey = `coach_r1_supplybase`; break;
                    case `relief`: impactDelta += 1; moatDelta -= 2; coachKey = `coach_r1_relief`; break;
                    case `hq`: moatDelta -= 1; break;
                }

                switch (d.institutionalize) {
                    case `embed`: moatDelta += 7; impactDelta += 3; coachKey = `coach_r1_embed`; break;
                    case `biggerfoundation`: moatDelta -= 3; impactDelta += 2; coachKey = `coach_r1_biggerfoundation`; break;
                    case `report`: moatDelta -= 1; break;
                }

                // Urgency = treating the shock as a strategy problem, not procurement.
                if (d.urgency >= 60) { moatDelta += 4; supplyDelta += 2; }
                else if (d.urgency <= 25) { moatDelta -= 3; supplyDelta -= 2; coachKey = `coach_r1_lowurgency`; }

                summaryKey = (d.diagnosis === `disconnected` && d.cocreate === `supplybase` && d.institutionalize === `embed`)
                    ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Redesign the business model. The two headline traps live here. ----
                const fuse = d.integration / 100;

                if (d.model === `scalecsr`) {
                    // HEADLINE ANTI-PATTERN: scaling the foundation = philanthropy in disguise.
                    // Sticky flag — gates the top verdict and caps moat/supply for the run.
                    ds.philanthropyRun = true;
                    impactDelta += 6;            // genuine goodwill...
                    moatDelta -= 6;              // ...but it builds NO advantage
                    supplyDelta -= 2;            // and does nothing for secured supply
                    roiDelta -= 2;
                    coachKey = `coach_r2_scalecsr`;
                } else if (d.model === `squeeze`) {
                    // Pure cost extraction trap.
                    ds.extractionRun = true;
                    roiDelta += 4;               // costs drop this year...
                    impactDelta -= 12;           // ...farmer income falls below living income
                    supplyDelta -= 8;            // attrition accelerates, base ages out
                    moatDelta -= 5;
                    coachKey = `coach_r2_squeeze`;
                } else if (d.model === `sharedvalue`) {
                    // Farmer-equity shared-value sourcing — the modelled path.
                    impactDelta += 14;
                    supplyDelta += 12;
                    moatDelta += 9;
                    roiDelta += 5 + fuse * 4;
                    coachKey = `coach_r2_sharedvalue`;
                } else if (d.model === `platform`) {
                    // Digital farmer-services platform — secures supply BECAUSE it lifts incomes.
                    impactDelta += 12;
                    supplyDelta += 10;
                    moatDelta += 12;             // proprietary data + relationships = strong moat
                    roiDelta += 4 + fuse * 4;
                    coachKey = `coach_r2_platform`;
                }

                // Embedding logic — structural vs bolt-on / marketing overlay.
                switch (d.embed) {
                    case `structural`: moatDelta += 6; impactDelta += 3; supplyDelta += 3; break;
                    case `bolton`: moatDelta -= 5; coachKey = `coach_r2_bolton`; break;
                    case `marketing`: ds.copyableRun = true; moatDelta -= 6; coachKey = `coach_r2_marketing`; break;
                }

                // Source of advantage / barrier to imitation (decision tree #5).
                switch (d.moatSource) {
                    case `relationships`: moatDelta += 10; supplyDelta += 4; break;
                    case `claim`: ds.copyableRun = true; moatDelta -= 6; coachKey = `coach_r2_claim`; break;
                    case `price`: ds.extractionRun = true; moatDelta -= 7; impactDelta -= 4; coachKey = `coach_r2_pricemoat`; break;
                }

                // Fusing supply and impact into one mechanism (the I4I core).
                if (fuse >= 0.6) { moatDelta += 5; supplyDelta += 4; impactDelta += 3; }
                else if (fuse <= 0.25) { moatDelta -= 4; coachKey = `coach_r2_lowfuse`; }

                summaryKey = ((d.model === `sharedvalue` || d.model === `platform`) && d.embed === `structural` && d.moatSource === `relationships`)
                    ? `sum_r2_good`
                    : (d.model === `scalecsr` ? `sum_r2_philanthropy`
                    : (d.model === `squeeze` ? `sum_r2_extraction` : `sum_r2_weak`));
            } else if (round === 3) {
                // ---- Allocate ₱1.2B against the dual constraint + governance. ----
                switch (d.alloc) {
                    case `integrated`: roiDelta += 8; impactDelta += 8; moatDelta += 5; supplyDelta += 4; break;
                    case `splitbudget`: ds.splitBudgetRun = true; roiDelta += 1; moatDelta -= 6; coachKey = `coach_r3_split`; break;
                    case `reliefheavy`: ds.philanthropyRun = true; impactDelta += 4; roiDelta -= 5; moatDelta -= 6; supplyDelta -= 2; coachKey = `coach_r3_relief`; break;
                    case `thin`: roiDelta -= 3; moatDelta -= 3; coachKey = `coach_r3_thin`; break;
                }

                switch (d.governance) {
                    case `pandlowner`: moatDelta += 9; roiDelta += 3; impactDelta += 3; break;
                    case `sustainabilityoffice`: ds.noOwnershipRun = true; moatDelta -= 7; coachKey = `coach_r3_office`; break;
                    case `foundation`: ds.noOwnershipRun = true; ds.philanthropyRun = true; moatDelta -= 6; coachKey = `coach_r3_foundation`; break;
                }

                switch (d.drivers) {
                    case `allthree`: moatDelta += 8; impactDelta += 3; roiDelta += 2; break;
                    case `purposeonly`: moatDelta += 1; coachKey = `coach_r3_purposeonly`; break;
                    case `none`: moatDelta -= 4; coachKey = `coach_r3_nodrivers`; break;
                }

                switch (d.metric) {
                    case `securedincome`: moatDelta += 6; impactDelta += 2; supplyDelta += 2; break;
                    case `goodwill`: ds.philanthropyRun = true; moatDelta -= 5; coachKey = `coach_r3_goodwillmetric`; break;
                    case `costonly`: ds.extractionRun = true; impactDelta -= 4; moatDelta -= 4; break;
                }

                // Dual-constraint discipline lever (ROI ≥ 18% AND impact lift).
                const disc = d.hurdle / 100;
                roiDelta += disc * 10 - 2;            // discipline pulls return toward/over the hurdle
                impactDelta += disc * 5;
                if (d.hurdle <= 25) { roiDelta -= 3; coachKey = `coach_r3_undisciplined`; }

                summaryKey = (d.alloc === `integrated` && d.governance === `pandlowner` && d.drivers === `allthree` && d.metric === `securedincome`)
                    ? `sum_r3_good`
                    : (ds.splitBudgetRun ? `sum_r3_split`
                    : (ds.noOwnershipRun ? `sum_r3_ownership` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Defend the strategy + absorb a shock. ----
                switch (d.defense) {
                    case `mechanism`: moatDelta += 7; impactDelta += 2; roiDelta += 2; coachKey = `coach_r4_mechanism`; break;
                    case `goodwill`: ds.philanthropyRun = true; moatDelta -= 6; coachKey = `coach_r4_goodwill`; break;
                    case `cheap`: ds.extractionRun = true; moatDelta -= 5; impactDelta -= 3; coachKey = `coach_r4_cheap`; break;
                }

                // The live shock — magnitude depends on how defensible the model is.
                const resilient = ds.moat >= 50 && !ds.philanthropyRun && !ds.extractionRun;
                if (d.response === `hold`) {
                    if (resilient) { moatDelta += 6; supplyDelta += 4; impactDelta += 2; coachKey = `coach_r4_hold_strong`; }
                    else { supplyDelta -= 4; moatDelta -= 2; coachKey = `coach_r4_hold_weak`; }
                } else if (d.response === `philanthropy`) {
                    ds.philanthropyRun = true;
                    impactDelta += 3; moatDelta -= 7; supplyDelta -= 5; coachKey = `coach_r4_resp_philanthropy`;
                } else if (d.response === `extraction`) {
                    ds.extractionRun = true;
                    roiDelta += 2; impactDelta -= 8; supplyDelta -= 8; moatDelta -= 6; coachKey = `coach_r4_resp_extraction`;
                }

                // Shock-specific bite when the model is NOT resilient.
                if (!resilient) {
                    if (d.shockSelect === `typhoon`) supplyDelta -= 6;
                    else if (d.shockSelect === `competitor`) supplyDelta -= 5;
                    else if (d.shockSelect === `ngo`) moatDelta -= 5;
                }

                switch (d.proof) {
                    case `securedlift`: moatDelta += 5; break;
                    case `donated`: ds.philanthropyRun = true; moatDelta -= 4; coachKey = `coach_r4_proof_donated`; break;
                    case `awareness`: moatDelta -= 3; coachKey = `coach_r4_proof_awareness`; break;
                }

                if (d.conviction >= 60) { moatDelta += 3; }
                else if (d.conviction <= 25) { moatDelta -= 3; }

                summaryKey = (d.defense === `mechanism` && d.response === `hold` && d.proof === `securedlift`)
                    ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.roi = Math.max(0, Math.min(40, Math.round((ds.roi + roiDelta) * 10) / 10));
            ds.impact = Math.max(0, Math.min(100, Math.round(ds.impact + impactDelta)));
            ds.supply = Math.max(0, Math.min(100, Math.round(ds.supply + supplyDelta)));
            ds.moat = Math.max(0, Math.min(100, Math.round(ds.moat + moatDelta)));

            // ---- ESG customer de-listing: extractive sourcing with no recovered impact
            // costs the 15%-of-revenue customer (decision tree #2). Sticky once tripped. ----
            if (ds.extractionRun && ds.impact < 45) {
                ds.delisted = true;
                ds.roi = Math.min(ds.roi, 12);   // losing 15% of revenue caps blended return below the hurdle
            }

            // ---- STICKY CAPS: the run-defining errors gate the KPIs so a later good
            // round cannot wash them out. The headline philanthropy anti-pattern can
            // NEVER build a defensible advantage. ----
            if (ds.philanthropyRun) {
                ds.moat = Math.min(ds.moat, 45);    // goodwill, not advantage -> capped below MOAT_TARGET
                ds.supply = Math.min(ds.supply, 84); // philanthropy never secures the supply
            }
            if (ds.extractionRun) {
                ds.moat = Math.min(ds.moat, 42);
                ds.impact = Math.min(ds.impact, 48); // extraction caps the inclusive-growth index
            }
            if (ds.copyableRun) {
                ds.moat = Math.min(ds.moat, 50);    // a copyable claim is not durable advantage
            }
            if (ds.noOwnershipRun) {
                ds.moat = Math.min(ds.moat, 52);    // cut at the first margin squeeze
            }
            if (ds.splitBudgetRun) {
                ds.moat = Math.min(ds.moat, 55);    // relabeled charity, not institutionalized I4I
            }

            ds.roiHistory.push(ds.roi);
            ds.impactHistory.push(ds.impact);
            ds.supplyHistory.push(ds.supply);
            ds.moatHistory.push(ds.moat);

            // ---- Persist the composite where the gradebook / reporting layer reads it. ----
            // express_resolveDomainScore() reads domainState.performance.overallScore first,
            // then a top-level score; express_extractHistory() reads the same per period.
            // Without this the instructor Results show "—", the per-period sparkline is empty
            // and the gametype-20 (record_grade / AGS) post-back sends 0.
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                roi: ds.roi,
                roiDelta: Math.round(roiDelta * 10) / 10,
                impact: ds.impact,
                impactDelta: Math.round(impactDelta),
                supply: ds.supply,
                supplyDelta: Math.round(supplyDelta),
                moat: ds.moat,
                moatDelta: Math.round(moatDelta),
                delisted: ds.delisted,
                verdict: this._verdictLabel(ds),
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        // The board's read on the strategy (also drives the verdict bar).
        _verdictLabel(ds) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const clears = ds.roi >= this.HURDLE;
            const impactful = ds.impact >= this.IMPACT_THRESHOLD;
            const secured = ds.supply >= this.SUPPLY_TARGET - 5;
            const defensible = ds.moat >= this.MOAT_TARGET;
            const headlineError = ds.philanthropyRun || ds.extractionRun;

            if (clears && impactful && secured && defensible && !headlineError) return t(`verdict_institutionalized`);
            if (ds.extractionRun || ds.delisted) return t(`verdict_extraction`);
            if (ds.philanthropyRun) return t(`verdict_philanthropy`);
            if (clears && impactful && (defensible || secured)) return t(`verdict_emerging`);
            return t(`verdict_relabeled`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`roiDisplay`, `domainState.roi`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.liwanag-card-roi`);
                if (card) {
                    card.classList.toggle(`liwanag-roi-clears`, n >= self.HURDLE);
                    card.classList.toggle(`liwanag-roi-misses`, n < self.HURDLE);
                }
                return `${self._fmtPct1(n)} / ${self.HURDLE}%`;
            });

            uiManager.bind(`impactDisplay`, `domainState.impact`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`supplyDisplay`, `domainState.supply`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.liwanag-card-supply`);
                if (card) card.classList.toggle(`liwanag-supply-low`, n < 80);
                return `${n}%`;
            });

            uiManager.bind(`moatDisplay`, `domainState.moat`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.liwanag-card-moat`);
                if (card) card.classList.toggle(`liwanag-moat-weak`, n < self.MOAT_TARGET);
                return `${n}`;
            });

            uiManager.bind(`verdictDisplay`, `domainState.moat`, () => {
                const ds = window.mySimulation.state.domainState;
                const bar = document.querySelector(`.liwanag-verdict-bar`);
                const good = ds.roi >= self.HURDLE && ds.impact >= self.IMPACT_THRESHOLD && ds.moat >= self.MOAT_TARGET && !ds.philanthropyRun && !ds.extractionRun;
                const mid = !good && ds.roi >= self.HURDLE && ds.impact >= self.IMPACT_THRESHOLD;
                if (bar) {
                    bar.classList.toggle(`liwanag-verdict-good`, good);
                    bar.classList.toggle(`liwanag-verdict-mid`, mid);
                }
                return self._verdictLabel(ds);
            });

            // Slider readouts.
            const sliders = [
                [`urgencyInput`, `urgencyReadout`],
                [`integrationInput`, `integrationReadout`],
                [`hurdleInput`, `hurdleReadout`]
            ];
            sliders.forEach(function(pair) {
                const el = document.getElementById(pair[0]);
                const out = document.getElementById(pair[1]);
                if (el && out) {
                    out.textContent = el.value;
                    el.addEventListener(`input`, function() { out.textContent = el.value; });
                }
            });

            // Accessibility: mirror each control's visible (data-i18n) prompt onto the
            // control via aria-label — the prompts are separate elements (no <label for>),
            // so a screen reader would otherwise announce an unlabeled <select>. The guard
            // skips any key that is not defined so no raw key is ever injected.
            const tA = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const ariaMap = {
                diagnosisInput: `r1_diagnosis_label`, cocreateInput: `r1_cocreate_label`,
                institutionalizeInput: `r1_institutionalize_label`, urgencyInput: `r1_urgency_label`,
                modelInput: `r2_model_label`, embedInput: `r2_embed_label`,
                moatSourceInput: `r2_moat_label`, integrationInput: `r2_integration_label`,
                allocInput: `r3_alloc_label`, governanceInput: `r3_governance_label`,
                driversInput: `r3_drivers_label`, metricInput: `r3_metric_label`, hurdleInput: `r3_hurdle_label`,
                defenseInput: `r4_defense_label`, shockSelectInput: `r4_shock_label`,
                responseInput: `r4_response_label`, proofInput: `r4_proof_label`, convictionInput: `r4_conviction_label`
            };
            Object.keys(ariaMap).forEach((id) => {
                const el = document.getElementById(id);
                if (!el) return;
                const lbl = tA(ariaMap[id]);
                if (lbl && lbl !== ariaMap[id]) el.setAttribute(`aria-label`, lbl);
            });
        }

        _fmtPct1(v) {
            // Locale-aware one-decimal percentage: en "18.0", es "18,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `%`;
        }

        getChartConfig() {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            return {
                liwanagChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t(`chart_ds_return`),
                                data: [],
                                borderColor: `#1f6f8b`,
                                backgroundColor: `rgba(31,111,139,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f6f8b`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_impact`),
                                data: [],
                                borderColor: `#2f6b3a`,
                                backgroundColor: `rgba(47,107,58,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6b3a`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_supply`),
                                data: [],
                                borderColor: `#b5852f`,
                                backgroundColor: `rgba(181,133,47,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b5852f`,
                                yAxisID: `y`
                            },
                            {
                                label: t(`chart_ds_moat`),
                                data: [],
                                borderColor: `#7d4ea8`,
                                backgroundColor: `rgba(125,78,168,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7d4ea8`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#5a4a36`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a7a62` }, grid: { color: `rgba(74,47,23,0.06)` },
                                title: { display: true, text: `0–100 (return shown as %)`, color: `#8a7a62` }
                            },
                            x: {
                                ticks: { color: `#8a7a62` }, grid: { color: `rgba(74,47,23,0.04)` },
                                title: { display: true, text: `Round`, color: `#8a7a62` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.roiHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                liwanagChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.roiHistory.map((v) => Math.round(v)) },
                        { data: ds.impactHistory },
                        { data: ds.supplyHistory },
                        { data: ds.moatHistory }
                    ]
                }
            };
        }

        // ---- Composite score — single source of truth. ----
        // Carries the VERBATIM v1.0.0 getPerformanceSummary formula so the score
        // persisted every period equals the completion composite by construction.
        _composite(ds) {
            const roi    = Math.round(ds.roi * 10) / 10;
            const impact = Math.round(ds.impact);
            const supply = Math.round(ds.supply);
            const moat   = Math.round(ds.moat);
            const roiScore = Math.max(0, Math.min(100, (roi / this.HURDLE) * 60));
            return Math.round(roiScore * 0.25 + impact * 0.25 + supply * 0.22 + moat * 0.28);
        }

        // Map the (stable, English) performance tier id to its localized label,
        // reusing the sim's existing verdict_* i18n keys.
        _gradeLabel(performance) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Institutionalized Social Innovation': `verdict_institutionalized`,
                'Emerging Advantage':                  `verdict_emerging`,
                'Extractive Sourcing':                 `verdict_extraction`,
                'Philanthropy in Disguise':            `verdict_philanthropy`,
                'Relabeled Charity':                   `verdict_relabeled`
            };
            return t(map[performance] || `verdict_relabeled`);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const roi = Math.round(ds.roi * 10) / 10;
            const impact = Math.round(ds.impact);
            const supply = Math.round(ds.supply);
            const moat = Math.round(ds.moat);

            const clears = roi >= this.HURDLE;
            const impactful = impact >= this.IMPACT_THRESHOLD;
            const secured = supply >= this.SUPPLY_TARGET - 5;
            const defensible = moat >= this.MOAT_TARGET;
            const headlineError = ds.philanthropyRun || ds.extractionRun;

            // Composite — computed by _composite(), the SAME helper persisted to
            // domainState.performance.overallScore each period, so the completion score
            // equals the last per-period score by construction.
            const composite = this._composite(ds);

            // Dominant pattern.
            let pattern = `relabeled`;
            if (ds.philanthropyRun) pattern = `philanthropy`;
            else if (ds.extractionRun || ds.delisted) pattern = `extraction`;
            else if (clears && impactful && secured && defensible) pattern = `institutionalized`;
            else pattern = `relabeled`;

            // Performance verdict — the top tier is GATED by the sticky error flags.
            let performance = `Philanthropy in Disguise`;
            if (clears && impactful && secured && defensible && !headlineError && composite >= 75) {
                performance = `Institutionalized Social Innovation`;
            } else if (clears && impactful && (defensible || secured) && !headlineError) {
                performance = `Emerging Advantage`;
            } else if (ds.extractionRun || ds.delisted) {
                performance = `Extractive Sourcing`;
            } else if (ds.philanthropyRun) {
                performance = `Philanthropy in Disguise`;
            } else {
                performance = `Relabeled Charity`;
            }

            const insights = [];
            if (pattern === `institutionalized`) insights.push(window.mySimulation.t(`insight_institutionalized`));
            else if (pattern === `philanthropy`) insights.push(window.mySimulation.t(`insight_philanthropy`));
            else if (pattern === `extraction`) insights.push(window.mySimulation.t(`insight_extraction`));
            else insights.push(window.mySimulation.t(`insight_relabeled`));

            if (!clears) insights.push(window.mySimulation.t(`insight_hurdle`));
            if (!impactful) insights.push(window.mySimulation.t(`insight_impact_low`));
            if (!secured) insights.push(window.mySimulation.t(`insight_supply_low`));
            if (!defensible) insights.push(window.mySimulation.t(`insight_moat_low`));
            if (ds.delisted) insights.push(window.mySimulation.t(`insight_delisted`));
            if (ds.noOwnershipRun) insights.push(window.mySimulation.t(`insight_ownership`));
            if (ds.splitBudgetRun) insights.push(window.mySimulation.t(`insight_split`));
            if (ds.copyableRun && !ds.philanthropyRun && !ds.extractionRun) insights.push(window.mySimulation.t(`insight_copyable`));

            return {
                roi: roi,
                impact: impact,
                supply: supply,
                moat: moat,
                clears: clears,
                impactful: impactful,
                secured: secured,
                defensible: defensible,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        // Localized completion debrief — the base class default only prints
        // "You completed N periods", discarding the composite, verdict, gates,
        // KPIs and insights this sim computes. Rendered into #usf-completion-content.
        formatCompletionMessage(summary) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const composite = Number.isFinite(s.composite) ? s.composite : this._composite(window.mySimulation.state.domainState);
            const verdict = s.performanceLabel || this._gradeLabel(s.performance || `Relabeled Charity`);
            const top = (s.performance === `Institutionalized Social Innovation`);
            const chip = (ok, label) =>
                `<span class="ii-cm-chip ${ok ? `ii-cm-chip-ok` : `ii-cm-chip-no`}">${ok ? `✓` : `✗`} ${label}</span>`;
            const kpi = (label, value, sub) =>
                `<div class="ii-cm-kpi"><div class="ii-cm-kpi-val">${value}</div>` +
                `<div class="ii-cm-kpi-lbl">${label}</div>` + (sub ? `<div class="ii-cm-kpi-sub">${sub}</div>` : ``) + `</div>`;
            const chips = [
                chip(!!s.clears,     t(`cm_t_roi`)),
                chip(!!s.impactful,  t(`cm_t_impact`)),
                chip(!!s.secured,    t(`cm_t_supply`)),
                chip(!!s.defensible, t(`cm_t_moat`))
            ].join(``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<div class="ii-cm-h">${t(`cm_insights_h`)}</div><ul class="ii-cm-insights">` +
                  insights.map((x) => `<li>${x}</li>`).join(``) + `</ul>` : ``;
            return `
                <div class="ii-cm ${top ? `ii-cm-top` : ``}">
                    <div class="ii-cm-verdict">
                        <div class="ii-cm-score"><span class="ii-cm-score-num">${composite}</span><span class="ii-cm-score-den">/100</span></div>
                        <div class="ii-cm-verdict-txt">
                            <div class="ii-cm-badge">${verdict}</div>
                            <div class="ii-cm-sub">${t(`cm_periods_pre`)} ${s.totalPeriods || 4} ${t(`cm_periods_post`)}</div>
                        </div>
                    </div>
                    <div class="ii-cm-h">${t(`cm_targets_h`)}</div>
                    <div class="ii-cm-chips">${chips}</div>
                    <div class="ii-cm-h">${t(`cm_kpis_h`)}</div>
                    <div class="ii-cm-kpis">
                        ${kpi(t(`roi_label`), this._fmtPct1(Number(s.roi) || 0), t(`cm_target`) + ` ` + this.HURDLE + `%`)}
                        ${kpi(t(`impact_label`), Math.round(Number(s.impact) || 0), t(`cm_target`) + ` ` + this.IMPACT_THRESHOLD)}
                        ${kpi(t(`supply_label`), Math.round(Number(s.supply) || 0) + `%`, t(`cm_target`) + ` ` + this.SUPPLY_TARGET + `%`)}
                        ${kpi(t(`moat_label`), Math.round(Number(s.moat) || 0), t(`cm_target`) + ` ` + this.MOAT_TARGET)}
                    </div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.delisted) return window.mySimulation.t(`hint_delisted`);
            if (ds.philanthropyRun) return window.mySimulation.t(`hint_philanthropy`);
            if (ds.extractionRun) return window.mySimulation.t(`hint_extraction`);
            if (ds.roi < this.HURDLE && state.currentPeriod >= 3) return window.mySimulation.t(`hint_hurdle`);
            if (ds.moat < this.MOAT_TARGET && state.currentPeriod >= 2) return window.mySimulation.t(`hint_moat`);
            if (ds.supply < 85 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_supply`);
            if (ds.roi >= this.HURDLE && ds.impact >= this.IMPACT_THRESHOLD && ds.moat >= this.MOAT_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.roi`, label: `Return`, i18nKey: `col_roi`, formatter: (v) => self._fmtPct1(Number(v)) },
                { key: `results.impact`, label: `Impact`, i18nKey: `col_impact`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.supply`, label: `Supply`, i18nKey: `col_supply`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.moat`, label: `Advantage`, i18nKey: `col_moat`, formatter: (v) => `${Math.round(v)}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

